<tr data-kendala-id="{{ $k->id }}" data-search="{{ strtolower($k->perihal.' '.($k->tujuanSatuan->nama ?? '')) }}" data-prioritas="{{ $k->prioritas }}"><td>{{ $k->perihal }}</td><td style="text-align:center"><span class="satuan-pill">{{ $k->tujuanSatuan->kode ?? $k->tujuanSatuan->nama ?? '-' }}</span></td><td><span class="priority-tag prio-{{ strtolower($k->prioritas) }}">{{ $k->prioritas }}</span></td><td style="text-align:center"><span class="status-dot {{ in_array($k->status, ['Ditindaklanjuti','Selesai'], true) ? 'green' : ($k->status === 'Ditolak' ? 'bad' : 'amber') }}">{{ $k->status }}</span></td><td style="text-align:center">{{ $k->created_at->translatedFormat('d M Y H:i') }}</td><td><div class="review-actions" style="justify-content:center"><button type="button" class="detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($satuan->nama) }}" data-tujuan="{{ e($k->tujuanSatuan->nama ?? '-') }}" data-perihal="{{ e($k->perihal) }}" data-prioritas="{{ e($k->prioritas) }}" data-tanggal="{{ e($k->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($k->deskripsi) }}" data-kendala="{{ e($k->catatan ?? '') }}" data-lampiran="{{ $k->lampiran_path ? e(asset('storage/'.$k->lampiran_path)) : '' }}" data-readonly="1" data-readonly-text="Laporan kendala ini sudah Anda kirim — status saat ini: {{ $k->status }}.">Detail</button></div></td></tr>
